def verify_archive(folder):
 root=folder/'remote';manifest=json.loads((folder/'execution.json').read_text())['manifest'];assert sha(folder/'raw.zip')==json.loads((folder/'collection.json').read_text())['archive_sha256'];assert all(sha(root/n)==m['sha256'] and (root/n).stat().st_size==m['bytes'] for n,m in manifest.items());return root,len(manifest)
