 folder=ROOT/'evidence/20261124-3060-ncu-smoke-v2';raw,count=verify_archive(folder/'segmented-archive');failed,failed_count=verify_archive(ROOT/'evidence/20261124-3060-ncu-smoke/recovered-archive');assert json.loads((failed/'result.json').read_text())['status']=='NCU_COLLECTION_FAILED' and "can't open file" in (failed/'container.stderr').read_text() and not (failed/'cublas.ncu-rep').exists();result=json.loads((raw/'result.json').read_text());assert result['status']=='NCU_COLLECTION_PASS' and result['exit']==0 and result['new_formal_event_samples']==result['new_model_calls']==0 and not result['production_runtime_changed'];plan=json.loads((raw/'plan.json').read_text());assert plan['metrics']==HARDWARE_METRICS+LAUNCH_METRICS and plan['target_launches']==3 and plan['clock_control']=='none';exe=json.loads((raw/'cublas.execution.json').read_text());assert exe['exit']==0 and exe['cleanup']['removed'] and exe['metrics']==plan['metrics'];assert all(sha(raw/'source'/n)==h for n,h in json.loads((folder/'source-hashes.json').read_text()).items());assert sha(raw/'source/experiments/p1_04/ncu_adapter.py')==sha(ROOT/'experiments/p1_04/ncu_adapter.py');assert sha(raw/'artifact/nka_gemm_v1.so')==result['binary_sha256']==plan['binary_sha256']
