  a=np.load(raw/('output-'+str(i)+'.npy'),allow_pickle=False);assert a.shape==(512,512) and a.dtype==np.float32 and np.isfinite(a).all();error=np.abs(a.astype(np.float64)-reference.astype(np.float64));assert np.all(error<=3e-5+1e-4*np.abs(reference));maximum=max(maximum,float(error.max()))
